parameters.text:
={{ `[INICIO DE CONTEXTO COMPARTIDO]
Resumen previo:
${$json.last_summary}

Datos relevantes acumulados:
${$json.key_data}

Mensaje actual del usuario:
${$json.chatInput}

Resultado actual:
${JSON.stringify({
  worker: $json.worker,
  status: $json.status,
  data: $json.data
})}
[FIN DEL CONTEXTO COMPARTIDO]` }}

assignments.value:
={{ {
  resumen_consolidado: JSON.stringify($json.output),
  datos_clave: $json.output.puntos_clave.join('\n'),
  estado_caso:
    $('Preparar actualización de memoria').first().json.status === 'error'
      ? 'error'
      : $('Preparar actualización de memoria').first().json.status === 'revision_humana'
        ? 'revision_humana'
        : (
          $('Preparar actualización de memoria').first().json.data?.estado
          || 'en_proceso'
        )
} }}

